const NIVEL = {critico:'#8e1b1b', alto:'#e8743b', moderado:'#f0b429', baixo:'#bcd4f2'};
const NIVEL_LBL = {critico:'Crítico', alto:'Alto', moderado:'Moderado', baixo:'Baixo'};
const fmt = n => n.toLocaleString('pt-BR');
const byUF = {}; DB.estados.forEach(e=>byUF[e.uf]=e);


/* ---------- navegação entre páginas ---------- */
const nav = document.getElementById('nav');
const menuBtn = document.getElementById('menuBtn');
const sidebar = document.getElementById('sidebar');
const backdrop = document.createElement('div');
backdrop.className = 'sidebar-backdrop';
document.body.appendChild(backdrop);

function closeSidebar(){
  if (!sidebar) return;
  sidebar.classList.remove('open');
  backdrop.classList.remove('show');
  document.body.classList.remove('no-scroll');
}

if (menuBtn && sidebar) {
  menuBtn.setAttribute('aria-label', 'Abrir menu de navegação');
  menuBtn.addEventListener('click', () => {
    const isOpen = sidebar.classList.toggle('open');
    backdrop.classList.toggle('show', isOpen);
    document.body.classList.toggle('no-scroll', isOpen);
  });
  backdrop.addEventListener('click', closeSidebar);
  document.addEventListener('keydown', (event) => {
    if (event.key === 'Escape') closeSidebar();
  });
  document.querySelectorAll('.nav a').forEach(link => {
    link.addEventListener('click', closeSidebar);
  });
}

/* ---------- maps ---------- */
function heatColor(inc){
  const t = Math.min(1, inc/900);
  if(inc<50) return '#5a6b7d';
  const stops=[[90,107,125],[244,196,48],[232,116,59],[142,27,27]];
  const seg = t*3; const i=Math.min(2,Math.floor(seg)); const f=seg-i;
  const a=stops[i], b=stops[i+1];
  const c=a.map((v,k)=>Math.round(v+(b[k]-v)*f));
  return `rgb(${c[0]},${c[1]},${c[2]})`;
}
function buildMap(containerId, mode){
  const wrap = document.getElementById(containerId);
  if (!wrap) return null;
  let paths='';
  MAP.states.forEach(s=>{
    const e = byUF[s.sigla]||{inc:0,nivel:'baixo'};
    const fill = mode==='heat' ? heatColor(e.inc) : NIVEL[e.nivel];
    paths += `<path class="st" data-uf="${s.sigla}" d="${s.d}" fill="${fill}"></path>`;
  });
  let labels='';
  MAP.states.forEach(s=>{ labels+=`<text class="maplabel" x="${s.cx}" y="${s.cy}">${s.sigla}</text>`; });
  wrap.innerHTML = `<svg viewBox="0 0 ${MAP.width} ${MAP.height}" preserveAspectRatio="xMidYMid meet">${paths}${labels}</svg>`;
  return wrap;
}
const maptip = document.getElementById('maptip');
function attachTip(wrap){
  if (!wrap || !maptip) return;
  wrap.querySelectorAll('.st').forEach(p=>{
    p.addEventListener('mousemove', ev=>{
      const e = byUF[p.dataset.uf]; if(!e) return;
      maptip.innerHTML = `<b>${e.nome}</b> · ${fmt(e.casos)} casos<br>${e.inc.toLocaleString('pt-BR')} /100k · ${NIVEL_LBL[e.nivel]}`;
      maptip.style.left = ev.clientX+'px'; maptip.style.top = ev.clientY+'px'; maptip.style.opacity=1;
    });
    p.addEventListener('mouseleave', ()=>maptip.style.opacity=0);
  });
}

function kpiCard(lbl,val,chip,dir,pct,cls){
  return `<div class="card kpi"><div class="lbl">${lbl}</div>
    <div class="val ${cls}">${val}</div>
    <div style="display:flex;justify-content:space-between;align-items:center;margin-bottom:9px">
      <span class="chip ${dir}">${dir==='up'?'↗':'↘'} ${chip}</span></div>
    <div class="bar ${cls}"><i style="width:${pct}%"></i></div></div>`;
}
function kpiCardCrit(lbl,val){
  return `<div class="card kpi"><div class="lbl">${lbl}<span class="tag crit">CRÍTICO</span></div>
    <div class="val">${val}</div><div style="height:21px"></div>
    <div class="bar"><i style="width:48%"></i></div></div>`;
}

function renderGeral(){
  const sub = document.getElementById('geral-sub');
  const kpis = document.getElementById('kpis');
  const ranking = document.getElementById('ranking');
  if (!sub || !kpis || !ranking) return;
  const k = DB.kpis;
  sub.textContent = `Dados consolidados do Sistema de Informação de Agravos de Notificação (SINAN) — Semana Epidemiológica ${DB.kpis.sem_epi}`;
  kpis.innerHTML = `
    ${kpiCard('Casos Prováveis', fmt(k.casos), `+${k.casos_var}%`,'up',72,'')}
    ${kpiCard('Óbitos Confirmados', fmt(k.obitos), `+${k.obitos_var}%`,'up',38,'red')}
    ${kpiCard('Taxa de Letalidade', k.letalidade.toLocaleString('pt-BR')+'%', `${k.let_var}%`,'down',14,'')}
    ${kpiCardCrit('Surtos Ativos', fmt(k.surtos))}`;
  const wrap = buildMap('heatmap','heat');
  if (wrap) {
    wrap.insertAdjacentHTML('beforeend', `<div class="legend">
      <h4>LEGENDA DE RISCO</h4>
      <div class="li"><span class="sw" style="background:#8e1b1b"></span>Crítico (&gt; 500 casos)</div>
      <div class="li"><span class="sw" style="background:#e8743b"></span>Alto (200 - 500)</div>
      <div class="li"><span class="sw" style="background:#f0b429"></span>Moderado (50 - 200)</div>
      <div class="li"><span class="sw" style="background:#bcd4f2"></span>Baixo (&lt; 50)</div></div>`);
    attachTip(wrap);
  }
  const topStates = [...DB.estados].sort((a,b)=>b.casos-a.casos).slice(0,5);
  const maxCasos = topStates[0].casos;
  const rankColors = ['#b8202e','#1c6fd0','#2f7fd6','#5a9be0','#86b8ec'];
  ranking.innerHTML = topStates.map((e,i)=>`
    <div class="rk"><div class="top"><span style="color:var(--ink)">${e.nome}</span><span>${(e.casos/1000).toFixed(0)}k casos</span></div>
    <div class="bar"><i style="width:${(e.casos/maxCasos*100).toFixed(1)}%;background:${rankColors[i]}"></i></div></div>`).join('');
}

function renderRegSide(e){
  const regside = document.getElementById('regside');
  if (!regside) return;
  const incPct = Math.min(100, e.inc/600*100);
  regside.innerHTML = `
   <div class="card statcard"><div class="lbl">Total na região selecionada</div>
     <div class="big">${fmt(e.casos)} <span class="chip ${e.var>=0?'up':'down'}" style="font-size:11px">${e.var>=0?'↗':'↘'}${Math.abs(e.var)}%</span></div>
     <div class="sub">${e.nome} · Casos notificados (Semanas 01-${DB.cur_week})</div></div>
   <div class="card statcard"><div class="lbl">Taxa de Incidência</div>
     <div class="big">${e.inc.toLocaleString('pt-BR')} <small>/100k hab.</small></div>
     <div class="incbar"><i style="width:${incPct}%"></i></div></div>
   <div class="card statcard"><div class="lbl" style="margin-bottom:14px">Evolução Semanal</div>
     <div class="bars" id="evolbars"></div>
     <div class="barlabels"><span>SEM 08</span><span>SEM ${String(DB.evol[DB.evol.length-1].sem).slice(-2)}</span></div></div>`;
  const ev = DB.evol; const mx = Math.max(...ev.map(x=>x.val));
  const hl = ev.reduce((a,b,i)=> b.val>ev[a].val?i:a,0);
  document.getElementById('evolbars').innerHTML = ev.map((x,i)=>{
    const scale = 0.8 + (e.casos % 7)/20;
    return `<div class="b ${i===hl?'hl':''}" style="height:${Math.max(12,x.val/mx*120*scale)}px" title="${x.sem}: ${fmt(x.val)}"></div>`;
  }).join('');
}

function renderRegional(){
  const wrap = buildMap('regmap','nivel');
  if (!wrap) return;
  wrap.insertAdjacentHTML('beforeend', `<div class="legend">
    <h4>LEGENDA DE RISCO</h4>
    <div class="li"><span class="sw" style="background:#8e1b1b"></span>Crítico (&gt; 500 casos)</div>
    <div class="li"><span class="sw" style="background:#e8743b"></span>Alto (200 - 500)</div>
    <div class="li"><span class="sw" style="background:#f0b429"></span>Moderado (50 - 200)</div>
    <div class="li"><span class="sw" style="background:#bcd4f2"></span>Baixo (&lt; 50)</div></div>
    <div class="maphint" id="maphint"><svg viewBox="0 0 24 24"><path d="M12 21s-7-6.7-7-12a7 7 0 0 1 14 0c0 5.3-7 12-7 12Z"/><circle cx="12" cy="9" r="2.3"/></svg>Interativo: Clique para filtrar</div>`);
  attachTip(wrap);
  wrap.querySelectorAll('.st').forEach(p=>{
    p.addEventListener('click',()=>{
      wrap.querySelectorAll('.st').forEach(x=>x.classList.remove('sel'));
      p.classList.add('sel');
      const hint = document.getElementById('maphint');
      if (hint) hint.style.display='none';
      renderRegSide(byUF[p.dataset.uf]);
    });
  });
  renderRegSide(byUF['SP']);
}

function drawLineChart(){
  const host = document.getElementById('linechart');
  if (!host) return;
  const W=640, H=340, P={l:8,r:18,t:18,b:26};
  const weeks = DB.semanas;
  const all = weeks.map(w=>w.hist).concat(weeks.filter(w=>w.atual).map(w=>w.atual), DB.pred.map(p=>p.high));
  const maxY = Math.max(...all)*1.08, minY=0;
  const totalW = weeks.length + 4;
  const X = i => P.l + (i/(totalW-1))*(W-P.l-P.r);
  const Y = v => P.t + (1-(v-minY)/(maxY-minY))*(H-P.t-P.b);
  const histPath = weeks.map((w,i)=>`${i?'L':'M'}${X(i).toFixed(1)},${Y(w.hist).toFixed(1)}`).join('');
  const curWeeks = weeks.filter(w=>w.atual!=null);
  const curPath = curWeeks.map((w,i)=>`${i?'L':'M'}${X(w.w-1).toFixed(1)},${Y(w.atual).toFixed(1)}`).join('');
  const predPath = DB.pred.map((p,i)=>`${i?'L':'M'}${X(p.w-1).toFixed(1)},${Y(p.val).toFixed(1)}`).join('');
  const bandTop = DB.pred.map((p,i)=>`${i?'L':'M'}${X(p.w-1).toFixed(1)},${Y(p.high).toFixed(1)}`).join('');
  const bandBot = DB.pred.slice().reverse().map((p,i)=>`L${X(p.w-1).toFixed(1)},${Y(p.low).toFixed(1)}`).join('');
  const band = bandTop+bandBot+'Z';
  host.innerHTML = `<svg viewBox="0 0 ${W} ${H}" style="width:100%;height:auto;background:#f7f9fc;border-radius:10px" id="lcsvg">
    <path d="${band}" fill="rgba(28,111,208,.14)"/>
    <path d="${histPath}" fill="none" stroke="#c3ccd8" stroke-width="2.4" stroke-dasharray="6 5"/>
    <path d="${curPath}" fill="none" stroke="var(--brand)" stroke-width="3"/>
    <path d="${predPath}" fill="none" stroke="var(--brand2)" stroke-width="2.6" stroke-dasharray="2 5" stroke-linecap="round"/>
    <line id="vline" x1="0" y1="${P.t}" x2="0" y2="${H-P.b}" stroke="#9fb3cc" stroke-width="1" stroke-dasharray="3 3" opacity="0"/>
  </svg>`;
  const svg = document.getElementById('lcsvg');
  const tip = document.getElementById('charttip');
  const vline = document.getElementById('vline');
  if (!svg || !tip || !vline) return;
  svg.addEventListener('mousemove', ev=>{
    const r = svg.getBoundingClientRect();
    const px = (ev.clientX-r.left)/r.width*W;
    let idx = Math.round((px-P.l)/(W-P.l-P.r)*(totalW-1));
    idx = Math.max(0, Math.min(weeks.length-1, idx));
    const w = weeks[idx];
    const xx = X(idx);
    vline.setAttribute('x1',xx); vline.setAttribute('x2',xx); vline.setAttribute('opacity','1');
    const diff = w.atual!=null ? Math.round((w.atual-w.hist)/w.hist*100) : null;
    tip.innerHTML = `<b>Semana Epidemiológica ${w.w}</b>`+(w.atual!=null?`Casos: ${fmt(w.atual)} (${diff>=0?'+':''}${diff}%)<br>`:'')+`Histórico: ${fmt(w.hist)}`;
    tip.style.left = (r.left + xx/W*r.width)+'px';
    tip.style.top = (r.top + Y(w.atual||w.hist)/H*r.height)+'px';
    tip.style.opacity=1;
  });
  svg.addEventListener('mouseleave', ()=>{tip.style.opacity=0; vline.setAttribute('opacity','0');});
}

function renderTrend(region){
  const trendrows = document.getElementById('trendrows');
  if (!trendrows) return;
  const rows = DB.estados.filter(e=>e.regiao===region).sort((a,b)=>b.semana-a.semana).slice(0,4);
  trendrows.innerHTML = rows.map(e=>{
    const dir = e.var>=8?'up':(e.var<=-3?'down':'flat');
    const arr = dir==='up'?'↗':(dir==='down'?'↘':'→');
    const projColor = e.status==='Crescente'?'#b8202e':(e.status==='Estável'?'#3f6db5':'#1f9d57');
    const projW = e.status==='Crescente'?78:(e.status==='Estável'?45:28);
    const tagcls = e.tag==='Crítico'?'crit':(e.tag==='Alerta'?'alerta':'ok');
    return `<tr><td class="uf">${e.nome}</td><td>${fmt(e.semana)}</td>
      <td><span class="arrow ${dir}">${arr} ${e.var>=0?'+':''}${e.var}%</span></td>
      <td>${e.inc.toLocaleString('pt-BR')}</td>
      <td><div class="miniproj"><div class="track"><i style="width:${projW}%;background:${projColor}"></i></div>${e.status}</div></td>
      <td style="text-align:right"><span class="tag ${tagcls}">${e.tag.toUpperCase()}</span></td></tr>`;
  }).join('');
}

function renderTendencias(){
  const predpct = document.getElementById('predpct');
  if (!predpct) return;
  const k = DB.kpis;
  predpct.textContent = `+${DB.pred_pct}%`;
  drawLineChart();
  const alertlist = document.getElementById('alertlist');
  if (alertlist) alertlist.innerHTML = DB.alertas.slice(0,2).map(a=>`
    <div class="al ${a.nivel==='alto'?'hi':''}"><div class="alhead"><b>${a.mun}</b><span class="mini">${a.tag}</span></div><p>${a.txt}</p></div>`).join('');
  renderTrend('Sudeste');
  const regtabs = document.getElementById('regtabs');
  if (regtabs) regtabs.addEventListener('click', e=>{
    const b=e.target.closest('button'); if(!b) return;
    document.querySelectorAll('#regtabs button').forEach(x=>x.classList.remove('on'));
    b.classList.add('on'); renderTrend(b.dataset.r);
  });
  const conf = document.getElementById('ms-conf');
  const epi = document.getElementById('ms-epi');
  const letal = document.getElementById('ms-let');
  if (conf) conf.innerHTML = `${k.confiabilidade}% <small>Acurácia</small>`;
  if (epi) epi.innerHTML = `${k.mun_epidemia} <small style="color:var(--crit)">+${k.mun_epidemia_var} esta sem.</small>`;
  if (letal) letal.innerHTML = `0.03% <small>Meta: &lt;0.05%</small>`;
}

function renderPrevencao(){
  const checklist = document.getElementById('checklist');
  if (!checklist) return;
  const checks = ['Eliminar criadouros em focos críticos','Aplicação de larvicida (conforme protocolo)','Orientação direta aos moradores','Registro de dados no sistema móvel'];
  checklist.innerHTML = checks.map((c,i)=>`
    <div class="ck" data-i="${i}"><div class="box"><svg viewBox="0 0 24 24"><path d="M5 12l5 5L20 6"/></svg></div><span>${c}</span></div>`).join('');
  checklist.addEventListener('click', e=>{
    const ck=e.target.closest('.ck'); if(ck) ck.classList.toggle('done');
  });
}

renderGeral();
renderRegional();
renderTendencias();
renderPrevencao();
